export type Category = 'eat' | 'tour' | 'stay' | 'beach' | 'events';

export function catPath(c: Category): string {
  return c === 'eat'
    ? ICON_PATHS.coffee
    : c === 'tour'
      ? ICON_PATHS.nav
      : c === 'stay'
        ? ICON_PATHS.home
        : c === 'beach'
          ? ICON_PATHS.waves
          : ICON_PATHS.cal;
}

export type Place = {
  id: string;
  name: string;
  area: string;
  cat: Category;
  catLabel: string;
  /** Short chip label for the full (12-way) category. */
  catShort?: string;
  tint: string;
  /** Cover photo. Empty for directory places → PhotoBlock renders the tinted hatch. */
  image: string;
  tags: string[];
  price: string;
  priceLabel: string;
  hours: string;
  best: string;
  travel: string;
  openNow: boolean;
  blurb: string;

  // ── Directory extras (real Google Places data) ──────────────────────────
  /** True GPS latitude — projected on the offline Map screen. */
  lat?: number;
  /** True GPS longitude — projected on the offline Map screen. */
  lng?: number;
  rating?: number;
  reviews?: number;
  phone?: string;
  address?: string;
  /** Google Maps place page (photos + full reviews). */
  mapsUrl?: string;
  /** Google Maps turn-by-turn directions deep link. */
  dirsUrl?: string;
  placeId?: string;
  /** Full 12-way category label. */
  category?: string;
};

/** Build a sized, format-optimized Unsplash URL from a photo id. */
export function unsplash(id: string, w = 800): string {
  return `https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=70`;
}

/** Every place, in the compiled directory order. */
export const ALL_PLACES: Place[] = DIRECTORY;

/** The catalog keyed by slug. */
export const PLACES: Record<string, Place> = Object.fromEntries(
  DIRECTORY.map((p) => [p.id, p]),
);

export const PLACE_IDS = Object.keys(PLACES);

// ── Editorial helpers — always resolve to real slugs ────────────────────────

const fmtInt = (n: number) => n.toLocaleString('en-US');

/** Rank by rating weighted by (log) review volume, so busy + loved wins. */
function score(p: Place): number {
  return (p.rating ?? 0) * Math.log10((p.reviews ?? 0) + 10);
}
function inCats(labels: string[]): Place[] {
  return DIRECTORY.filter((p) => labels.includes(p.category ?? ''));
}
function topBy(arr: Place[], n: number): string[] {
  return [...arr].sort((a, b) => score(b) - score(a)).slice(0, n).map((p) => p.id);
}

/** Iconic featured spot for the Discover hero. */
export const FEATURED_ID: string =
  PLACES['cloud-9-surfing-area']?.id ?? topBy(inCats(['Things To Do']), 1)[0] ?? PLACE_IDS[0];

