/** Explore category filter chips — "All" + the 12 real directory categories. */
export type CategoryFilter = { key: string; label: string; tint: string };
export const CATEGORY_FILTERS: CategoryFilter[] = [
  { key: 'all', label: 'All', tint: '#0E7C86' },
  ...DIRECTORY_CATEGORIES.map((c) => ({ key: c.label, label: c.short, tint: c.tint })),
];

export function placeInCategory(p: Place, key: string): boolean {
  return key === 'all' || (p.category ?? p.catLabel) === key;
}

