export type ItineraryItem = { placeId: string; timeLabel: string; path: string };
export type ItineraryDay = { label: string; date: string; items: ItineraryItem[] };

const pick = (labels: string[], skip: Set<string>): string => {
  for (const id of topBy(inCats(labels), 12)) if (!skip.has(id)) { skip.add(id); return id; }
  return PLACE_IDS[0];
};
