/** Detail-screen "facts" strip, built from the real directory fields. */
export function placeFacts(p: Place) {
  return [
    { path: ICON_PATHS.star, label: 'Rating', value: p.rating ? `★ ${p.rating.toFixed(1)}` : 'New' },
    { path: ICON_PATHS.clock, label: 'Hours', value: p.hours },
    { path: catPath(p.cat), label: 'Category', value: p.catShort ?? p.catLabel },
    { path: ICON_PATHS.pin, label: 'Area', value: p.area },
    { path: ICON_PATHS.message, label: 'Reviews', value: p.reviews ? fmtInt(p.reviews) : '—' },
  ];
}

/** Build a "Good to know" list from a place's real details. */
export function placeTips(p: Place): string[] {
  const tips: string[] = [];
  if (p.rating) tips.push(`Rated ★ ${p.rating.toFixed(1)}${p.reviews ? ` from ${fmtInt(p.reviews)} reviews` : ''}`);
  if (p.hours && p.hours !== 'Hours vary') tips.push(`Hours: ${p.hours}`);
  if (p.address) tips.push(p.address);
  if (p.phone) tips.push(`Call or WhatsApp: ${p.phone}`);
  tips.push('Hours, prices and ATM availability change often — verify locally.');
  return tips;
}
